export function AgentIcon({ id, size = 24, className }: Props) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, '');

  if (id === 'hermes') {
    return (
      <img
        src={hermesIcon}
        alt="Hermes Agent"
        width={size}
        height={size}
        className={className}
        style={{ borderRadius: '22%', objectFit: 'cover', display: 'block' }}
        draggable={false}
      />
    );
  }

  // 1. OpenAI 官方 Codex
  if (id === 'codex') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <defs>
          <linearGradient id={`codex-${uid}`} x1="12" x2="12" y1="3" y2="21" gradientUnits="userSpaceOnUse">
            <stop stopColor="#B1A7FF" />
            <stop offset=".5" stopColor="#7A9DFF" />
            <stop offset="1" stopColor="#3941FF" />
          </linearGradient>
        </defs>
        <path d={CODEX_BG} fill="#ffffff" />
        <path d={CODEX_GLYPH} fill={`url(#codex-${uid})`} />
      </svg>
    );
  }

  // 2. Anthropic 官方 Claude
  if (id === 'claude') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <path fill="#D97757" fillRule="evenodd" d={CLAUDE_PATH} />
      </svg>
    );
  }

  // 3. Cursor 官方 3D 立方切角 Logo
  if (id === 'cursor') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <path fill="#ffffff" fillRule="evenodd" d={CURSOR_PATH} />
      </svg>
    );
  }

  // 4. DeepSeek 官方完整蓝鲸 Logo
  if (id === 'deepseek_harness') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <path fill="#2563eb" fillRule="evenodd" d={DEEPSEEK_PATH} />
      </svg>
    );
  }

  // 5. xAI 官方 Grok Logo
  if (id === 'grok') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <path fill="#ffffff" fillRule="evenodd" d={GROK_PATH} />
      </svg>
    );
  }

  // 6. ByteDance Trae 官方 Pixel Pal 机器人眼睛 Logo
  if (id === 'tare') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <path fill="#00d664" fillRule="evenodd" d={TRAE_PATH} />
      </svg>
    );
  }

  // 7. QCoder / 通义千问 Qwen 官方螺线量子结 Logo
  if (id === 'qcoder') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <defs>
          <linearGradient id={`qwen-${uid}`} x1="2" x2="22" y1="2" y2="22" gradientUnits="userSpaceOnUse">
            <stop stopColor="#7c3aed" />
            <stop offset="1" stopColor="#4f46e5" />
          </linearGradient>
        </defs>
        <path fill={`url(#qwen-${uid})`} fillRule="evenodd" d={QWEN_PATH} />
      </svg>
    );
  }

  // 8. ZCode / 智谱 Zhipu AI 官方引力网络 Logo
  if (id === 'zcode') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <path fill="#3859FF" fillRule="evenodd" d={ZHIPU_PATH} />
      </svg>
    );
  }

  // 9. OpenCode 官方开箱几何 Logo
  if (id === 'opencode') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <path fill="#ffffff" fillRule="evenodd" d={OPENCODE_PATH} />
      </svg>
    );
  }

  // 10. Google 官方 Gemini 四角星 Spark Logo（蓝→紫→珊瑚红官方渐变）
  if (id === 'gemini') {
    return (
      <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
        <defs>
          <linearGradient id={`gemini-${uid}`} x1="2" y1="2" x2="22" y2="22" gradientUnits="userSpaceOnUse">
            <stop stopColor="#4285F4" />
            <stop offset=".5" stopColor="#9B72CB" />
            <stop offset="1" stopColor="#D96570" />
          </linearGradient>
        </defs>
        <path
          fill={`url(#gemini-${uid})`}
          fillRule="evenodd"
          clipRule="evenodd"
          d={GEMINI_SPARK}
          transform="translate(2 2) scale(0.390625) translate(-210.569 0)"
        />
      </svg>
    );
  }

  // 自定义 Agent 或兜底
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} className={className} aria-hidden="true">
      <circle cx="12" cy="12" r="9" fill="none" stroke="currentColor" strokeWidth="2" opacity="0.4" />
      <text x="12" y="15.5" fontSize="11" fontWeight="bold" textAnchor="middle" fill="currentColor">
        {String(id).slice(0, 1).toUpperCase()}
      </text>
    </svg>
  );
}
